from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class CardNimCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        self.initial_hand = None
        self.opponent_played = []

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        cards, stones, opponent_card_played = data

        if self.initial_hand is None:
            self.initial_hand = cards.copy()

        if opponent_card_played is not None:
            self.opponent_played.append(opponent_card_played)

        opponent_remaining = set(self.initial_hand) - set(self.opponent_played)
        player_remaining = set(cards)

        playable = sorted([c for c in cards if c <= stones], reverse=True)
        chosen_card = None

        for c in playable:
            new_stones = stones - c
            new_player_remaining = player_remaining - {c}
            if not self._can_win(new_stones, frozenset(opponent_remaining), frozenset(new_player_remaining)):
                chosen_card = c
                break

        if not chosen_card and playable:
            chosen_card = playable[0]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_card, type='custom')]
        )

    @lru_cache(maxsize=None)
    def _can_win(self, stones: int, current_player_cards: frozenset, other_player_cards: frozenset) -> bool:
        if stones == 0:
            return False

        playable = [c for c in current_player_cards if c <= stones]
        if not playable:
            return False

        for c in playable:
            new_stones = stones - c
            new_current = current_player_cards - {c}
            if not self._can_win(new_stones, other_player_cards, new_current):
                return True
        return False

