            self.opponent_remaining_cards = list(cards)
        else:
            if opponent_card_played is not None and opponent_card_played in self.opponent_remaining_cards:
                self.opponent_remaining_cards.remove(opponent_card_played)

        playable = [c for c in cards if c <= stones]
        if not playable:
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )

        chosen_card = None
        # Check for immediate win
        for card in sorted(playable, reverse=True):
            if card == stones:
                chosen_card = card
                break

        if chosen_card is None:
            # Check for moves that leave opponent in losing state
            for card in sorted(playable, reverse=True):
                new_stones = stones - card
                my_new_cards = tuple(sorted(c for c in cards if c != card))
                opponent_cards = tuple(sorted(self.opponent_remaining_cards))
                if not self.can_win(new_stones, opponent_cards, my_new_cards):
                    chosen_card = card
                    break

            if chosen_card is None:
                chosen_card = min(playable)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_card, type='custom')]
        )

