    @lru_cache(maxsize=None)
    def can_win(stones, current_player_cards, other_player_cards):
        current_cards = set(current_player_cards)
        other_cards = set(other_player_cards)

        for card in current_cards:
            if card > stones:
                continue
            new_stones = stones - card
